class ratio { 
public: 
    static constexpr intmax_t num;   // Compile-time computed numerator after GCD simplification 
    static constexpr intmax_t den;   // Compile-time computed denominator after GCD simplification 
    typedef ratio<num, den> type;    // Alias for the simplified ratio type 
}; 
// Implementation Note: The compiler uses template metaprogramming (e.g., recursive templates or std::gcd) to compute GCD at compile time, ensuring num and den are reduced before code generation.

