#include <ratio>
#include <iostream>
int main() {
    constexpr auto numerator = std::ratio<4, 6>::num;  // Simplified to 2 at compile time
    constexpr auto denominator = std::ratio<4, 6>::den;  // Simplified to 3 at compile time
    std::cout << "Numerator: " << numerator << ", Denominator: " << denominator << std::endl;
